cssRules:
.master-detail-split {
  display: flex;
  height: 100%;
  overflow: hidden;
}
.split-master {
  width: 320px;
  flex-shrink: 0;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
  overflow-y: auto;
  padding: 12px;
}
.split-detail {
  flex: 1;
  overflow-y: auto;
  padding: 24px;
  background: rgba(255, 255, 255, 0.01);
}
